#include <stdio.h>
#include <math.h>

#define MAX_N 100
#define MAX_PAIRS (MAX_N * (MAX_N - 1) / 2)
#define ITERATIONS 1000
#define EPS 1e-12

typedef struct {
    double x, y;
} Point;

// Intersection of two lines: a1*x + b1*y = c1 and a2*x + b2*y = c2
int intersect(double a1, double b1, double c1,
              double a2, double b2, double c2,
              double *x, double *y) {
    double det = a1 * b2 - a2 * b1;
    if (fabs(det) < 1e-12) return 0; // parallel or coincident
    *x = (c1 * b2 - c2 * b1) / det;
    *y = (a1 * c2 - a2 * c1) / det;
    return 1;
}

int main() {
    int n;
    scanf("%d", &n);

    double a[MAX_N], b[MAX_N], c[MAX_N];
    for (int i = 0; i < n; i++) {
        scanf("%lf %lf %lf", &a[i], &b[i], &c[i]);
    }

    Point pts[MAX_PAIRS];
    int m = 0;

    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            double x, y;
            if (intersect(a[i], b[i], c[i], a[j], b[j], c[j], &x, &y)) {
                pts[m].x = x;
                pts[m].y = y;
                m++;
            }
        }
    }

    if (m == 0) {
        // No intersections: pick arbitrary point, e.g. (0,0)
        printf("0.000000 0.000000\n");
        return 0;
    }

    // Initial guess: centroid
    double sx = 0, sy = 0;
    for (int i = 0; i < m; i++) {
        sx += pts[i].x;
        sy += pts[i].y;
    }
    double gx = sx / m, gy = sy / m;

    // Weiszfeld iteration
    for (int iter = 0; iter < ITERATIONS; iter++) {
        double num_x = 0, num_y = 0, denom = 0;
        for (int i = 0; i < m; i++) {
            double dx = gx - pts[i].x;
            double dy = gy - pts[i].y;
            double dist = sqrt(dx * dx + dy * dy);
            if (dist < EPS) {
                // If exactly at a point, we can't divide by zero; just skip or nudge
                continue;
            }
            double w = 1.0 / dist;
            num_x += pts[i].x * w;
            num_y += pts[i].y * w;
            denom += w;
        }
        if (denom < EPS) break;
        double new_gx = num_x / denom;
        double new_gy = num_y / denom;
        if (fabs(new_gx - gx) < 1e-12 && fabs(new_gy - gy) < 1e-12) {
            gx = new_gx;
            gy = new_gy;
            break;
        }
        gx = new_gx;
        gy = new_gy;
    }

    printf("%.6f %.6f\n", gx, gy);
    return 0;
}

