        scanf("%lf %lf %lf", &A[i], &B[i], &C[i]);

    // Compute all intersection points
    int m = 0;
    double pts[n*n][2];
    for (int i = 0; i < n; i++)
        for (int j = i+1; j < n; j++) {
            double det = A[i]*B[j] - A[j]*B[i];
            if (fabs(det) < 1e-9) continue;
            double x = (C[i]*B[j] - C[j]*B[i]) / det;
            double y = (A[i]*C[j] - A[j]*C[i]) / det;
            pts[m][0] = x; pts[m][1] = y; m++;
        }

    // Weiszfeld's algorithm
    double cx = 0, cy = 0;
    for (int i = 0; i < m; i++) { cx += pts[i][0]; cy += pts[i][1]; }
    cx /= m; cy /= m;

    for (int iter = 0; iter < 1000; iter++) {
        double nx = 0, ny = 0, w = 0;
        for (int i = 0; i < m; i++) {
            double d = sqrt((cx-pts[i][0])*(cx-pts[i][0])+(cy-pts[i][1])*(cy-pts[i][1]));
            if (d < 1e-10) d = 1e-10;
            nx += pts[i][0]/d; ny += pts[i][1]/d; w += 1.0/d;
        }
        cx = nx/w; cy = ny/w;
    }

    // Evaluate geometric median and all intersection points
    double best_dist = 1e300, best_x = cx, best_y = cy;
    // add weiszfeld result and all pts
    double cands[m+1][2];
    for (int i = 0; i < m; i++) { cands[i][0]=pts[i][0]; cands[i][1]=pts[i][1]; }
    cands[m][0]=cx; cands[m][1]=cy;

    for (int k = 0; k <= m; k++) {
        double tx = cands[k][0], ty = cands[k][1], td = 0;
        for (int i = 0; i < m; i++)
            td += sqrt((tx-pts[i][0])*(tx-pts[i][0])+(ty-pts[i][1])*(ty-pts[i][1]));
        if (td < best_dist - 1e-9 || (fabs(td-best_dist)<1e-9 && (tx < best_x-1e-9 || (fabs(tx-best_x)<1e-9 && ty < best_y-1e-9))))
        { best_dist=td; best_x=tx; best_y=ty; }
    }

    printf("%.6f %.6f\n", best_x, best_y);
}

