typedef struct {
    double x, y;
} Point;

static const double EPS = 1e-12;

/* Compare doubles with tolerance */
static int dcmp(double a, double b) {
    double d = a - b;
    if (fabs(d) <= EPS) return 0;
    return d < 0 ? -1 : 1;
}

/* Euclidean distance */
static double dist(Point a, Point b) {
    double dx = a.x - b.x;
    double dy = a.y - b.y;
    return sqrt(dx * dx + dy * dy);
}

/*
Weiszfeld iteration for geometric median of points with weights 1.
If current point coincides with one of the data points, that point is optimal
for the subgradient condition if the norm of sum of unit vectors to other points <= multiplicity.
For this problem, simple stabilized Weiszfeld is sufficient.
*/
static Point geometric_median(Point *p, int m) {
    Point cur = {0.0, 0.0};
    for (int i = 0; i < m; i++) {
        cur.x += p[i].x;
        cur.y += p[i].y;
    }
    cur.x /= m;
    cur.y /= m;

    for (int it = 0; it < 10000; it++) {
        double numx = 0.0, numy = 0.0, den = 0.0;
        int hit = -1;

        for (int i = 0; i < m; i++) {
            double d = dist(cur, p[i]);
            if (d < 1e-15) {
                hit = i;
                break;
            }
            numx += p[i].x / d;
            numy += p[i].y / d;
            den += 1.0 / d;
        }

        Point nxt;
        if (hit != -1) {
            /* Slight perturbation not needed; point is already extremely close to data point.
               Keep it and stop. */
            nxt = p[hit];
        } else {
            nxt.x = numx / den;
            nxt.y = numy / den;
        }

        if (dist(cur, nxt) < 1e-13) {
            cur = nxt;
            break;
        }
        cur = nxt;
    }

    return cur;
}

static double total_distance(Point q, Point *p, int m) {
    double s = 0.0;
    for (int i = 0; i < m; i++) s += dist(q, p[i]);
    return s;
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    double *A = (double *)malloc(sizeof(double) * N);
    double *B = (double *)malloc(sizeof(double) * N);
    double *C = (double *)malloc(sizeof(double) * N);

    for (int i = 0; i < N; i++) {
        scanf("%lf %lf %lf", &A[i], &B[i], &C[i]);
    }

    long long maxPairs = 1LL * N * (N - 1) / 2;
    Point *pts = (Point *)malloc(sizeof(Point) * (size_t)maxPairs);

    int m = 0;
    for (int i = 0; i < N; i++) {
        for (int j = i + 1; j < N; j++) {
            double det = A[i] * B[j] - A[j] * B[i];
            if (fabs(det) <= EPS) continue; /* Parallel or coincident: no unique intersection */
            pts[m].x = (C[i] * B[j] - C[j] * B[i]) / det;
            pts[m].y = (A[i] * C[j] - A[j] * C[i]) / det;
            m++;
        }
    }

    if (m == 0) {
        /* No unique intersections */
        printf("0.0000000000 0.0000000000\n");
        free(A); free(B); free(C); free(pts);
        return 0;
    }

    Point ans = geometric_median(pts, m);

    /*
      Tie-breaking:
      For sum of distances, the minimizer set is convex. In degenerate tie cases,
      prefer smallest x, then smallest y.
      Numerically, if multiple nearby points give same objective, checking all data points
      helps with common degenerate cases. We also compare the computed median itself.
    */
    Point best = ans;
    double bestVal = total_distance(best, pts, m);

    for (int i = 0; i < m; i++) {
        double v = total_distance(pts[i], pts, m);
        if (v < bestVal - 1e-10 ||
            (fabs(v - bestVal) <= 1e-10 &&
             (dcmp(pts[i].x, best.x) < 0 ||
              (dcmp(pts[i].x, best.x) == 0 && dcmp(pts[i].y, best.y) < 0)))) {
            best = pts[i];
            bestVal = v;
        }
    }

    printf("%.10f %.10f\n", best.x, best.y);

    free(A);
    free(B);
    free(C);
    free(pts);
    return 0;
}

