struct Line {
    long long A, B, C;
};

pair<double,double> intersect(Line l1, Line l2) {
    long long det = l1.A * l2.B - l2.A * l1.B;
    if (det == 0) {
        // parallel or coincident, skip in problem context
        return {0,0};
    }
    double x = (double)(l2.B * l1.C - l1.B * l2.C) / det;
    double y = (double)(l1.A * l2.C - l2.A * l1.C) / det;
    return {x, y};
}

