/*
We are given N lines: A_i x + B_i y = C_i.
For every pair of non-parallel lines, there is a car at their intersection point.
We need the point minimizing the sum of Euclidean distances from all such points.
Tie-break: smallest x, then smallest y.

Key geometric fact:
The geometric median of a finite set of points minimizes sum of distances.
For a multiset of points, if all points lie on a single line, then every median point
on that line minimizing the 1D sum is optimal. With lexicographic tie-breaking,
we choose the smallest x, then y.

However, constructing all O(N^2) intersection points is infeasible in general.
We use a dual observation for lines:

Intersection of lines i and j:
det = A_i B_j - A_j B_i
x = (C_i B_j - C_j B_i) / det
y = (A_i C_j - A_j C_i) / det

The full general problem over arbitrary N is extremely hard without constraints,
and no constraints were provided. The only robust exact approach is to explicitly
enumerate all intersections and then compute the geometric median numerically.

So this solution assumes N is small enough for O(N^2) intersections.

Algorithm:
1. Enumerate all pairwise intersections of non-parallel lines.
2. If no intersections exist, output "0 0".
3. If there is only one point, output it.
4. Check if all points are collinear.
   - If yes, reduce to 1D median on the line parameter t = dot(P, dir).
     Any t in [median_left, median_right] is optimal.
     Pick lexicographically smallest point among that interval.
5. Otherwise use Weiszfeld's algorithm to compute the geometric median.
   Since the objective is strictly convex unless collinear, the minimizer is unique.
   Start from centroid, iterate until convergence.
   If current iterate coincides with a data point, that is the solution.
6. Print with high precision.

*/

struct Point {
    long double x, y;
};

static const long double EPS = 1e-18L;

long double dist(const Point& a, const Point& b) {
    long double dx = a.x - b.x, dy = a.y - b.y;
    return sqrtl(dx * dx + dy * dy);
}

long double cross(const Point& a, const Point& b, const Point& c) {
    // (b-a) x (c-a)
    return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
}

bool all_collinear(const vector<Point>& pts) {
    int m = (int)pts.size();
    if (m <= 2) return true;
    int i = 1;
    while (i < m && fabsl(pts[i].x - pts[0].x) < 1e-15L && fabsl(pts[i].y - pts[0].y) < 1e-15L) i++;
    if (i == m) return true;
    for (int j = i + 1; j < m; j++) {
        if (fabsl(cross(pts[0], pts[i], pts[j])) > 1e-12L) return false;
    }
    return true;
}

Point geometric_median_weiszfeld(const vector<Point>& pts) {
    Point cur{0, 0};
    for (auto &p : pts) {
        cur.x += p.x;
        cur.y += p.y;
    }
    cur.x /= pts.size();
    cur.y /= pts.size();

    for (int it = 0; it < 10000; it++) {
        long double numx = 0, numy = 0, den = 0;
        bool hit = false;
        for (auto &p : pts) {
            long double d = dist(cur, p);
            if (d < 1e-15L) {
                cur = p;
                hit = true;
                break;
            }
            long double w = 1.0L / d;
            numx += p.x * w;
            numy += p.y * w;
            den += w;
        }
        if (hit) break;
        Point nxt{numx / den, numy / den};
        if (dist(cur, nxt) < 1e-14L) {
            cur = nxt;
            break;
        }
        cur = nxt;
    }
    return cur;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<long double> A(N), B(N), C(N);
    for (int i = 0; i < N; i++) cin >> A[i] >> B[i] >> C[i];

    vector<Point> pts;
    for (int i = 0; i < N; i++) {
        for (int j = i + 1; j < N; j++) {
            long double det = A[i] * B[j] - A[j] * B[i];
            if (fabsl(det) < 1e-18L) continue; // parallel or coincident
            long double x = (C[i] * B[j] - C[j] * B[i]) / det;
            long double y = (A[i] * C[j] - A[j] * C[i]) / det;
            pts.push_back({x, y});
        }
    }

    if (pts.empty()) {
        cout << fixed << setprecision(12) << 0.0 << " " << 0.0 << "\n";
        return 0;
    }

    if ((int)pts.size() == 1) {
        cout << fixed << setprecision(12) << (double)pts[0].x << " " << (double)pts[0].y << "\n";
        return 0;
    }

    Point ans;

    if (all_collinear(pts)) {
        // Reduce to 1D median on the supporting line.
        Point p0 = pts[0], p1 = pts[1];
        int idx = 1;
        while (idx < (int)pts.size() &&
               fabsl(pts[idx].x - p0.x) < 1e-15L &&
               fabsl(pts[idx].y - p0.y) < 1e-15L) idx++;
        if (idx == (int)pts.size()) {
            ans = p0;
        } else {
            long double dx = pts[idx].x - p0.x;
            long double dy = pts[idx].y - p0.y;
            long double norm = sqrtl(dx * dx + dy * dy);
            dx /= norm; dy /= norm; // unit direction

            vector<long double> t;
            t.reserve(pts.size());
            for (auto &p : pts) {
                t.push_back((p.x - p0.x) * dx + (p.y - p0.y) * dy);
            }
            sort(t.begin(), t.end());
            int m = (int)t.size();
            long double L = t[(m - 1) / 2];
            long double R = t[m / 2];

            // Any point p0 + s*dir for s in [L,R] is optimal.
            // Need lexicographically smallest (x, then y).
            // x(s)=p0.x+dx*s, y(s)=p0.y+dy*s.
            long double s;
            if (fabsl(dx) > 1e-18L) {
                s = (dx > 0 ? L : R);
            } else {
                s = (dy > 0 ? L : R);
            }
            ans = {p0.x + dx * s, p0.y + dy * s};
        }
    } else {
        ans = geometric_median_weiszfeld(pts);
    }

    cout << fixed << setprecision(12) << (double)ans.x << " " << (double)ans.y << "\n";
    return 0;
}

