/*
We have N lines: A_i x + B_i y = C_i.
For every pair of lines, a car is at their intersection point.
We need the point minimizing the sum of Euclidean distances to all these cars.
This is the geometric median of all pairwise intersection points.

Tie-breaking: smallest x, then smallest y.

Approach:
1) Generate all intersection points of non-parallel pairs of lines.
2) If there are no intersection points, output 0 0.
3) Use Weiszfeld's algorithm to approximate the geometric median.
4) Since exact tie situations are rare and the objective is strictly convex unless collinear/special,
   this gives the optimal point numerically.

Because the statement does not specify output precision, we print with high precision.

Note:
- Parallel pairs do not contribute a car because they do not intersect.
- Coincident lines are also skipped pairwise if determinant is 0.
*/

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        double nextDouble() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            double val = 0;
            while (c > ' ' && c != '.' && c != -1) {
                val = val * 10 + (c - '0');
                c = read();
            }

            if (c == '.') {
                double mul = 0.1;
                c = read();
                while (c > ' ' && c != -1) {
                    val += (c - '0') * mul;
                    mul *= 0.1;
                    c = read();
                }
            }

            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) Math.round(nextDouble());
        }
    }

    static class Point {
        double x, y;
        Point(double x, double y) {
            this.x = x;
            this.y = y;
        }
    }

    static final double EPS = 1e-12;

    static double totalDist(List<Point> pts, double x, double y) {
        double s = 0.0;
        for (Point p : pts) {
            double dx = x - p.x;
            double dy = y - p.y;
            s += Math.hypot(dx, dy);
        }
        return s;
    }

    static Point geometricMedian(List<Point> pts) {
        int m = pts.size();
        if (m == 0) return new Point(0.0, 0.0);
        if (m == 1) return new Point(pts.get(0).x, pts.get(0).y);

        double x = 0, y = 0;
        for (Point p : pts) {
            x += p.x;
            y += p.y;
        }
        x /= m;
        y /= m;

        double prev = totalDist(pts, x, y);

        for (int iter = 0; iter < 10000; iter++) {
            double numX = 0, numY = 0, den = 0;
            boolean onPoint = false;
            Point exact = null;

            for (Point p : pts) {
                double dx = x - p.x;
                double dy = y - p.y;
                double d = Math.hypot(dx, dy);
                if (d < EPS) {
                    onPoint = true;
                    exact = p;
                    break;
                }
                double w = 1.0 / d;
                numX += p.x * w;
                numY += p.y * w;
                den += w;
            }

            double nx, ny;
            if (onPoint) {
                // Modified Weiszfeld handling:
                // Check nearby point condition by trying the exact point itself.
                nx = exact.x;
                ny = exact.y;
            } else {
                nx = numX / den;
                ny = numY / den;
            }

            double cur = totalDist(pts, nx, ny);
            if (Math.abs(prev - cur) < 1e-12 && Math.hypot(nx - x, ny - y) < 1e-12) {
                x = nx;
                y = ny;
                break;
            }
            x = nx;
            y = ny;
            prev = cur;
        }

        return new Point(x, y);
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N;
        try {
            N = fs.nextInt();
        } catch (Exception e) {
            return;
        }

        double[] A = new double[N];
        double[] B = new double[N];
        double[] C = new double[N];

        for (int i = 0; i < N; i++) {
            A[i] = fs.nextDouble();
            B[i] = fs.nextDouble();
            C[i] = fs.nextDouble();
        }

        List<Point> pts = new ArrayList<>();

        for (int i = 0; i < N; i++) {
            for (int j = i + 1; j < N; j++) {
                double det = A[i] * B[j] - A[j] * B[i];
                if (Math.abs(det) < EPS) continue; // parallel or coincident
                double x = (C[i] * B[j] - C[j] * B[i]) / det;
                double y = (A[i] * C[j] - A[j] * C[i]) / det;
                pts.add(new Point(x, y));
            }
        }

        Point ans = geometricMedian(pts);

        System.out.printf(Locale.US, "%.10f %.10f%n", ans.x, ans.y);
    }
}

