import sys
from fractions import Fraction

def det(a, b, c, d):
    return a * d - b * c

def line_intersection(L1, L2):
    A1, B1, C1 = L1
    A2, B2, C2 = L2
    D = det(A1, B1, A2, B2)
    if D == 0:
        return None
    x = Fraction(det(C1, B1, C2, B2), D)
    y = Fraction(det(A1, C1, A2, C2), D)
    return (x, y)

def median_fraction(arr):
    arr = sorted(arr)
    m = len(arr)
    if m % 2 == 1:
        return arr[m // 2]
    else:
        # Any point in [arr[m//2-1], arr[m//2]] minimizes sum of abs distances.
        # Tie-breaking asks for smallest coordinate.
        return arr[m // 2 - 1]

def format_fraction(fr):
    if fr.denominator == 1:
        return str(fr.numerator)
    # print as decimal if finite, else as p/q
    d = fr.denominator
    t = d
    while t % 2 == 0:
        t //= 2
    while t % 5 == 0:
        t //= 5
    if t == 1:
        s = f"{float(fr):.10f}".rstrip('0').rstrip('.')
        return s if s else "0"
    return f"{fr.numerator}/{fr.denominator}"

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    lines = []
    for _ in range(n):
        A = int(next(it))
        B = int(next(it))
        C = int(next(it))
        lines.append((A, B, C))

    points = []
    for i in range(n):
        for j in range(i + 1, n):
            p = line_intersection(lines[i], lines[j])
            if p is not None:
                points.append(p)

    # If there are no intersection points, default to origin.
    # (Problem statements of this type usually guarantee enough intersections.)
    if not points:
        print("0 0")
        return

    xs = [p[0] for p in points]
    ys = [p[1] for p in points]

    ans_x = median_fraction(xs)
    ans_y = median_fraction(ys)

    print(format_fraction(ans_x), format_fraction(ans_y))

if __name__ == "__main__":
    solve()
